556	  RESIDENT_NEW: 60,            // 60/40
557	  RESIDENT_FULL_SUPPORT: 50,   // 50/50 when shop covers everything
558	  GUEST: 80,                   // 80/20 in guest's favor
559	  APPRENTICE: 50,              // 50/50 ramp
560	  BOOTH_RENTER: 100,           // booth renter keeps everything (rent invoiced separately)
561	} as const;
562	
563	// =====================================================================
564	// INVARIANTS — Sage scans verify these hold across the codebase
565	// =====================================================================
566	
567	/**
568	 * INVARIANT 1: All money is CentsAmount. Never `number` for money.
569	 * INVARIANT 2: Every Stripe call carries `metadata.inkos_idempotency_key`.
570	 * INVARIANT 3: Every webhook handler's first write is webhook_event_insert.
571	 * INVARIANT 4: `application_fee_amount` is set on every PaymentIntent (never undefined).
572	 * INVARIANT 5: Refunds always pass `reverse_transfer: true` AND `refund_application_fee: true`.
573	 * INVARIANT 6: `subscriptions` and `stripe_charges` are webhook-only writes from app code.
574	 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
575	 * INVARIANT 8: Banker's rounding when computing splits to avoid systematic bias.
576	 */
