/**
 * Stripe Connect Express onboarding helpers — Sprint 15.
 *
 * Server-side only. Never import from client components.
 *
 * Every Stripe SDK call goes through withIdempotencyKey() (INVARIANT 2).
 * No Stripe call is made without metadata.inkos_idempotency_key.
 *
 * INVARIANT 7: This module is Stripe-only. Never import from lib/dodo/*.
 */
import type { SupabaseClient } from '@supabase/supabase-js'
import { getStripe } from './client'
import { idempotencyKeyFor, withIdempotencyKey } from './idempotency'
import {
  RPC,
  type Currency,
  type ConnectedAccountType,
  type StripeConnectedAccountCreateArgs,
  type StripeConnectedAccountCreateResult,
} from '@/lib/payments/contracts'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface CreateConnectAccountArgs {
  studioId: string
  type: ConnectedAccountType
  /** Required when type='artist'. */
  artistId?: string
  /** ISO 3166-1 alpha-2. E.g. 'US', 'GB', 'AU'. */
  country: string
  defaultCurrency: Currency
  /** Verified email — Stripe uses this to pre-fill the KYC form. */
  email: string
}

export interface CreateConnectAccountResult {
  /** InkOS DB row id (UUID). */
  rowId: string
  /** Stripe acct_xxx. */
  accountId: string
}

export interface CreateAccountLinkArgs {
  accountId: string
  /** Where Stripe redirects after successful completion. */
  returnUrl: string
  /**
   * Where Stripe redirects when the link has expired or the user clicked
   * back. This is the GET /api/billing/connect/refresh-link endpoint URL.
   */
  refreshUrl: string
}

export interface AccountLinkResult {
  url: string
  /** Unix timestamp (seconds). Stripe account links expire ~5 minutes after creation. */
  expiresAt: number
}

// ---------------------------------------------------------------------------
// createConnectAccount
// ---------------------------------------------------------------------------

/**
 * Create a new Stripe Connect Express account for a studio or artist, then
 * record it via the stripe_connected_account_create RPC.
 *
 * IDEMPOTENCY: keyed by (studio_id, type, artist_id?) — retrying the same
 * logical operation returns the same Stripe account (Stripe dedupes by key).
 * The RPC is also idempotent: it inserts with ON CONFLICT DO NOTHING.
 *
 * Capabilities requested:
 *  - card_payments + transfers: always (required for platform charges)
 *  - tax_reporting_us_1099_nec: only for artist accounts (1099-NEC annual export)
 *
 * Metadata carried on Stripe account (for webhook reconciliation):
 *  - inkos_idempotency_key
 *  - inkos_studio_id
 *  - inkos_account_type
 *  - inkos_artist_id (artist accounts only)
 */
export async function createConnectAccount(
  supabase: SupabaseClient,
  args: CreateConnectAccountArgs,
): Promise<CreateConnectAccountResult> {
  const stripe = getStripe()

  const idemKey = idempotencyKeyFor('connect.account.create', {
    studio_id: args.studioId,
    type: args.type,
    artist_id: args.artistId ?? null,
  })

  const account = await withIdempotencyKey(idemKey, (key) =>
    stripe.accounts.create(
      {
        type: 'express',
        country: args.country,
        default_currency: args.defaultCurrency,
        email: args.email,
        capabilities: {
          card_payments: { requested: true },
          transfers: { requested: true },
          // 1099-NEC reporting only makes sense for artist payee accounts
          ...(args.type === 'artist'
            ? { tax_reporting_us_1099_nec: { requested: true } }
            : {}),
        },
        metadata: {
          inkos_idempotency_key: key,
          inkos_studio_id: args.studioId,
          inkos_account_type: args.type,
          ...(args.artistId ? { inkos_artist_id: args.artistId } : {}),
        },
      },
      { idempotencyKey: key },
    ),
  )

  logger.info(
    { accountId: account.id, studioId: args.studioId, type: args.type },
    'stripe connect: express account created',
  )

  // Record in our DB via RPC — owned by Dato's migration
  const rpcArgs: StripeConnectedAccountCreateArgs = {
    studioId: args.studioId,
    type: args.type,
    artistId: args.artistId ?? null,
    accountId: account.id,
    country: args.country,
    defaultCurrency: args.defaultCurrency,
  }

  const { data, error } = await supabase.rpc(RPC.STRIPE_CONNECTED_ACCOUNT_CREATE, {
    p_studio_id: rpcArgs.studioId,
    p_type: rpcArgs.type,
    p_artist_id: rpcArgs.artistId,
    p_account_id: rpcArgs.accountId,
    p_country: rpcArgs.country,
    p_default_currency: rpcArgs.defaultCurrency,
  })

  if (error) {
    logger.error(
      { err: error, accountId: account.id, studioId: args.studioId },
      'stripe connect: failed to record connected account via RPC',
    )
    throw error
  }

  const result = data as StripeConnectedAccountCreateResult
  return { rowId: result.id, accountId: account.id }
}

// ---------------------------------------------------------------------------
// createAccountLink
// ---------------------------------------------------------------------------

/**
 * Generate a Stripe account_link for hosted KYC onboarding.
 *
 * Account links are SHORT-LIVED (~5 minutes). The frontend must redirect to
 * `url` immediately after this call. Never cache or store the URL.
 *
 * If the link expires before the user completes onboarding, Stripe redirects
 * the browser to `refreshUrl`. The refresh endpoint (/api/billing/connect/refresh-link)
 * calls this function again and issues a 302 to the new URL.
 *
 * NOTE: Stripe's accountLinks.create does NOT accept an idempotencyKey request
 * option (the SDK omits it from the method signature and Stripe returns a 400
 * if you pass it via the options object). This is documented Stripe behavior:
 * account links are ephemeral and intentionally non-idempotent — each call
 * generates a fresh short-lived URL. INVARIANT 2 therefore does not apply here.
 * The underlying Stripe account is already idempotency-protected at creation time.
 */
export async function createAccountLink(
  args: CreateAccountLinkArgs,
): Promise<AccountLinkResult> {
  const stripe = getStripe()

  const link = await stripe.accountLinks.create({
    account: args.accountId,
    type: 'account_onboarding',
    return_url: args.returnUrl,
    refresh_url: args.refreshUrl,
  })

  logger.info(
    { accountId: args.accountId, expiresAt: link.expires_at },
    'stripe connect: account link created',
  )

  return { url: link.url, expiresAt: link.expires_at }
}

// ---------------------------------------------------------------------------
// fetchAccountStatus
// ---------------------------------------------------------------------------

/**
 * Fetch current Stripe account state directly from the Stripe API.
 *
 * Used for stale-state recovery: if the `account.updated` webhook was missed
 * or delayed, this fetches ground truth from Stripe so the caller can sync
 * via the existing STRIPE_CONNECTED_ACCOUNT_UPDATE_FROM_WEBHOOK RPC.
 *
 * Do not call this on every status request — prefer the DB read (cheaper).
 * Reserve this for explicit "re-sync" user actions or admin tooling.
 */
export async function fetchAccountStatus(accountId: string) {
  const stripe = getStripe()
  return stripe.accounts.retrieve(accountId)
}

/**
 * Connect status query helper — Sprint 15.
 *
 * Reads the studio's Stripe Connect state from our DB (no live Stripe API call).
 * The `account.updated` webhook keeps the DB in sync.
 *
 * Consumed by:
 *  - GET /api/billing/connect/status
 *  - Track B: /settings/payments page
 *  - Track B: /dashboard Connect onboarding banner
 */
import type { SupabaseClient } from '@supabase/supabase-js'
import type { ConnectedAccountOnboardingStatus } from '@/lib/payments/contracts'
import { RPC } from '@/lib/payments/contracts'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ConnectStatusResult {
  /** Stripe acct_xxx. Null if no connected account exists yet. */
  account_id: string | null
  onboarding_status: ConnectedAccountOnboardingStatus | null
  capabilities: {
    charges_enabled: boolean
    payouts_enabled: boolean
    transfers: boolean
    tax_reporting_us_1099_nec: boolean
  } | null
  restricted_reason: string | null
  requirements_due_by: string | null
  /**
   * True only when: onboarding_status='active' AND capabilities.charges_enabled=true.
   * Computed in TS as a fallback until Track C's studio_l2_payments_enabled RPC lands.
   */
  enabled: boolean
  /**
   * Human-readable reason when enabled=false. Matches the RPC reason codes defined
   * in StudioL2PaymentsEnabledResult so UI copy can be keyed to these strings.
   */
  enabled_reason: string | null
}

export interface ArtistConnectStatusResult {
  account_id: string | null
  onboarding_status: ConnectedAccountOnboardingStatus | null
  capabilities: {
    charges_enabled: boolean
    payouts_enabled: boolean
    transfers: boolean
    tax_reporting_us_1099_nec: boolean
  } | null
  restricted_reason: string | null
  requirements_due_by: string | null
  enabled: boolean
  enabled_reason: string | null
}

// ---------------------------------------------------------------------------
// Raw DB row shape (mirrors StripeConnectedAccountRow from contracts.ts)
// The actual table is created by Track C migration — we type it here directly.
// ---------------------------------------------------------------------------

interface ConnectedAccountDbRow {
  account_id: string
  onboarding_status: ConnectedAccountOnboardingStatus
  capabilities: {
    charges_enabled: boolean
    payouts_enabled: boolean
    transfers: boolean
    tax_reporting_us_1099_nec: boolean
    [k: string]: boolean | undefined
  } | null
  restricted_reason: string | null
  requirements_due_by: string | null
}

// ---------------------------------------------------------------------------
// computeEnabledFromRow — TS fallback until Track C RPC ships
// ---------------------------------------------------------------------------

function computeEnabledFromRow(
  row: ConnectedAccountDbRow,
): { enabled: boolean; enabled_reason: string | null } {
  if (row.onboarding_status === 'rejected') {
    return { enabled: false, enabled_reason: 'onboarding_rejected' }
  }
  if (row.onboarding_status === 'restricted') {
    return { enabled: false, enabled_reason: 'onboarding_restricted' }
  }
  if (row.onboarding_status === 'pending') {
    return { enabled: false, enabled_reason: 'onboarding_pending' }
  }
  if (row.onboarding_status === 'active') {
    const chargesEnabled = row.capabilities?.charges_enabled === true
    if (!chargesEnabled) {
      return { enabled: false, enabled_reason: 'charges_disabled' }
    }
    return { enabled: true, enabled_reason: null }
  }
  return { enabled: false, enabled_reason: 'onboarding_pending' }
}

// ---------------------------------------------------------------------------
// getStudioConnectStatus
// ---------------------------------------------------------------------------

/**
 * Get the studio's Connect status for UI rendering. Reads from our DB
 * (no Stripe API call) — webhook keeps DB in sync.
 *
 * Tries the studio_l2_payments_enabled RPC first (Track C). Falls back to
 * TS computation if the RPC doesn't exist yet (pre-migration state).
 *
 * Returns a null-safe result: if the studio has no connected account at all,
 * returns { account_id: null, onboarding_status: null, enabled: false, ... }.
 */
export async function getStudioConnectStatus(
  supabase: SupabaseClient,
  studioId: string,
): Promise<ConnectStatusResult> {
  // Read the connected account row for this studio (type='studio')
  const { data: row, error } = await supabase
    .from('stripe_connected_accounts')
    .select(
      'account_id, onboarding_status, capabilities, restricted_reason, requirements_due_by',
    )
    .eq('studio_id', studioId)
    .eq('type', 'studio')
    .maybeSingle()

  if (error) {
    logger.error({ err: error, studioId }, 'connect-status: failed to read stripe_connected_accounts')
    throw error
  }

  if (!row) {
    return {
      account_id: null,
      onboarding_status: null,
      capabilities: null,
      restricted_reason: null,
      requirements_due_by: null,
      enabled: false,
      enabled_reason: 'no_connected_account',
    }
  }

  const dbRow = row as ConnectedAccountDbRow

  // Try the capability RPC (Track C). If not deployed yet, fall back to TS computation.
  try {
    const { data: rpcResult, error: rpcError } = await supabase.rpc(
      RPC.STUDIO_L2_PAYMENTS_ENABLED,
      { p_studio_id: studioId },
    )

    if (!rpcError && rpcResult) {
      const r = rpcResult as { enabled: boolean; reason: string | null }
      return {
        account_id: dbRow.account_id,
        onboarding_status: dbRow.onboarding_status,
        capabilities: dbRow.capabilities ?? null,
        restricted_reason: dbRow.restricted_reason,
        requirements_due_by: dbRow.requirements_due_by,
        enabled: r.enabled,
        enabled_reason: r.reason,
      }
    }

    // RPC returned an error (function not yet deployed) — fall through to TS fallback
    if (rpcError) {
      logger.warn(
        { err: rpcError, studioId },
        'connect-status: studio_l2_payments_enabled RPC not available — using TS fallback',
      )
    }
  } catch (rpcErr) {
    logger.warn(
      { err: rpcErr, studioId },
      'connect-status: studio_l2_payments_enabled RPC threw — using TS fallback',
    )
  }

  const { enabled, enabled_reason } = computeEnabledFromRow(dbRow)

  return {
    account_id: dbRow.account_id,
    onboarding_status: dbRow.onboarding_status,
    capabilities: dbRow.capabilities ?? null,
    restricted_reason: dbRow.restricted_reason,
    requirements_due_by: dbRow.requirements_due_by,
    enabled,
    enabled_reason,
  }
}

// ---------------------------------------------------------------------------
// getArtistConnectStatus
// ---------------------------------------------------------------------------

/**
 * Get an artist's Connect status. Reads from our DB — no Stripe API call.
 *
 * Tries the artist_l2_payouts_enabled RPC first. Falls back to TS computation.
 */
export async function getArtistConnectStatus(
  supabase: SupabaseClient,
  studioId: string,
  artistId: string,
): Promise<ArtistConnectStatusResult> {
  const { data: row, error } = await supabase
    .from('stripe_connected_accounts')
    .select(
      'account_id, onboarding_status, capabilities, restricted_reason, requirements_due_by',
    )
    .eq('studio_id', studioId)
    .eq('type', 'artist')
    .eq('artist_id', artistId)
    .maybeSingle()

  if (error) {
    logger.error(
      { err: error, studioId, artistId },
      'connect-status: failed to read stripe_connected_accounts for artist',
    )
    throw error
  }

  if (!row) {
    return {
      account_id: null,
      onboarding_status: null,
      capabilities: null,
      restricted_reason: null,
      requirements_due_by: null,
      enabled: false,
      enabled_reason: 'no_connected_account',
    }
  }

  const dbRow = row as ConnectedAccountDbRow

  // Try the capability RPC (Track C)
  try {
    const { data: rpcResult, error: rpcError } = await supabase.rpc(
      RPC.ARTIST_L2_PAYOUTS_ENABLED,
      { p_artist_id: artistId },
    )

    if (!rpcError && rpcResult) {
      const r = rpcResult as { enabled: boolean; reason: string | null }
      return {
        account_id: dbRow.account_id,
        onboarding_status: dbRow.onboarding_status,
        capabilities: dbRow.capabilities ?? null,
        restricted_reason: dbRow.restricted_reason,
        requirements_due_by: dbRow.requirements_due_by,
        enabled: r.enabled,
        enabled_reason: r.reason,
      }
    }

    if (rpcError) {
      logger.warn(
        { err: rpcError, artistId },
        'connect-status: artist_l2_payouts_enabled RPC not available — using TS fallback',
      )
    }
  } catch (rpcErr) {
    logger.warn(
      { err: rpcErr, artistId },
      'connect-status: artist_l2_payouts_enabled RPC threw — using TS fallback',
    )
  }

  // TS fallback for artist: active + payouts_enabled + transfers
  let enabled = false
  let enabled_reason: string | null = null

  if (dbRow.onboarding_status === 'rejected') {
    enabled_reason = 'onboarding_rejected'
  } else if (dbRow.onboarding_status === 'restricted') {
    enabled_reason = 'onboarding_restricted'
  } else if (dbRow.onboarding_status === 'pending') {
    enabled_reason = 'onboarding_pending'
  } else if (dbRow.onboarding_status === 'active') {
    const payoutsEnabled = dbRow.capabilities?.payouts_enabled === true
    const transfersEnabled = dbRow.capabilities?.transfers === true
    if (!payoutsEnabled) {
      enabled_reason = 'payouts_disabled'
    } else if (!transfersEnabled) {
      enabled_reason = 'transfers_disabled'
    } else {
      enabled = true
    }
  } else {
    enabled_reason = 'onboarding_pending'
  }

  return {
    account_id: dbRow.account_id,
    onboarding_status: dbRow.onboarding_status,
    capabilities: dbRow.capabilities ?? null,
    restricted_reason: dbRow.restricted_reason,
    requirements_due_by: dbRow.requirements_due_by,
    enabled,
    enabled_reason,
  }
}

/**
 * POST /api/billing/connect/onboard
 *
 * Creates a Stripe Connect Express account for the studio or an artist, records it
 * via the stripe_connected_account_create RPC, and returns a Stripe-hosted KYC URL.
 *
 * Authorization: authenticated session, studio owner or admin role.
 * Rate limit: authedRatelimit (60 req/min).
 *
 * Body: { type: 'studio' | 'artist'; artist_id?: string }
 * Response 200: { url: string; expires_at: number; account_id: string }
 * Response 409: { error: 'already_onboarded' } — account already active
 */
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createConnectAccount, createAccountLink } from '@/lib/stripe/connect'
import type { ConnectedAccountOnboardingStatus, ConnectedAccountType } from '@/lib/payments/contracts'

export const dynamic = 'force-dynamic'

const BodySchema = z.object({
  type: z.enum(['studio', 'artist']),
  /** Required when type='artist'. UUID of the artist. */
  artist_id: z.string().uuid().optional(),
})

// ---------------------------------------------------------------------------
// POST handler
// ---------------------------------------------------------------------------

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Step 1: Rate limit by IP
  const ip = getClientIp(req)
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Step 2: Auth — require authenticated session
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }

  // Step 3: Studio role check — owner or admin only
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json(
      { error: 'owner or admin role required to manage Connect onboarding' },
      { status: 403 },
    )
  }

  // Step 4: Parse and validate body
  const parsed = BodySchema.safeParse(await req.json().catch(() => ({})))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { type, artist_id: artistId } = parsed.data

  // artist_id is required when type='artist'
  if (type === 'artist' && !artistId) {
    return NextResponse.json(
      { error: 'artist_id is required when type is artist' },
      { status: 400 },
    )
  }

  const supabase = await createClient()
  const studioId = auth.studioId
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  // Step 5: If type='artist', verify artistId belongs to this studio and
  //         caller is the artist themselves OR a studio owner.
  if (type === 'artist' && artistId) {
    const { data: artist, error: artistErr } = await supabase
      .from('artists')
      .select('id, profile_id, studio_id')
      .eq('id', artistId)
      .eq('studio_id', studioId)
      .maybeSingle()

    if (artistErr) {
      logger.error({ err: artistErr, artistId, studioId }, 'connect onboard: artist lookup failed')
      return NextResponse.json({ error: 'internal error' }, { status: 500 })
    }

    if (!artist) {
      return NextResponse.json(
        { error: 'artist not found in this studio' },
        { status: 404 },
      )
    }

    // Caller must be studio owner/admin (already checked above) OR the artist themselves
    const isArtistSelf = artist.profile_id === auth.user.id
    const isOwnerOrAdmin = auth.role === 'owner' || auth.role === 'admin'
    if (!isOwnerOrAdmin && !isArtistSelf) {
      return NextResponse.json(
        { error: 'forbidden: you can only initiate onboarding for yourself or as studio owner/admin' },
        { status: 403 },
      )
    }
  }

  // Step 6: Check if a connected account already exists for this (studio, type, artist_id)
  let existingAccountId: string | null = null
  let existingOnboardingStatus: ConnectedAccountOnboardingStatus | null = null

  const accountQuery = supabase
    .from('stripe_connected_accounts')
    .select('account_id, onboarding_status')
    .eq('studio_id', studioId)
    .eq('type', type as ConnectedAccountType)

  if (type === 'artist' && artistId) {
    accountQuery.eq('artist_id', artistId)
  } else {
    accountQuery.is('artist_id', null)
  }

  const { data: existingAccount, error: accountErr } = await accountQuery.maybeSingle()

  if (accountErr) {
    logger.error(
      { err: accountErr, studioId, type },
      'connect onboard: failed to check existing connected account',
    )
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  if (existingAccount) {
    existingAccountId = existingAccount.account_id as string
    existingOnboardingStatus = existingAccount.onboarding_status as ConnectedAccountOnboardingStatus

    // Already fully onboarded — nothing to do
    if (existingOnboardingStatus === 'active') {
      return NextResponse.json({ error: 'already_onboarded' }, { status: 409 })
    }

    // Has a connected account in non-active state — reuse it, skip creation
    logger.info(
      { accountId: existingAccountId, status: existingOnboardingStatus },
      'connect onboard: reusing existing non-active account',
    )
  }

  // Step 7: If no existing account, create one
  let accountId: string

  if (!existingAccountId) {
    // Fetch studio email for Stripe KYC pre-fill
    const { data: studio, error: studioErr } = await supabase
      .from('studios')
      .select('contact_email, country, currency')
      .eq('id', studioId)
      .single()

    if (studioErr || !studio) {
      logger.error({ err: studioErr, studioId }, 'connect onboard: studio lookup failed')
      return NextResponse.json({ error: 'internal error' }, { status: 500 })
    }

    // Resolve email: for artist type, try to get their auth email; fallback to studio email
    let email = studio.contact_email as string
    if (type === 'artist' && artistId) {
      const { data: profile } = await supabase
        .from('profiles')
        .select('email')
        .eq('id', auth.user.id)
        .maybeSingle()
      if (profile?.email) {
        email = profile.email as string
      }
    }

    // country: use studio country (ISO 3166-1 alpha-2); default US if missing
    const country = (studio.country as string | null) ?? 'US'

    // currency: studio default; validate it's a supported Currency
    const rawCurrency = (studio.currency as string | null) ?? 'usd'
    const supportedCurrencies = ['usd', 'gbp', 'eur', 'aud', 'cad'] as const
    type SupportedCurrency = (typeof supportedCurrencies)[number]
    const defaultCurrency: SupportedCurrency = supportedCurrencies.includes(
      rawCurrency.toLowerCase() as SupportedCurrency,
    )
      ? (rawCurrency.toLowerCase() as SupportedCurrency)
      : 'usd'

    try {
      const result = await createConnectAccount(supabase, {
        studioId,
        type: type as ConnectedAccountType,
        artistId,
        country,
        defaultCurrency,
        email,
      })
      accountId = result.accountId
    } catch (err) {
      logger.error({ err, studioId, type }, 'connect onboard: account creation failed')
      return NextResponse.json({ error: 'failed to create connected account' }, { status: 500 })
    }
  } else {
    accountId = existingAccountId
  }

  // Step 8: Generate Stripe-hosted account link for KYC
  const typeParam = type
  const artistParam = artistId ?? ''
  const returnUrl = `${appUrl}/settings/payments?onboarding=complete&type=${typeParam}`
  const refreshUrl = `${appUrl}/api/billing/connect/refresh-link?type=${typeParam}&artist_id=${artistParam}`

  let linkUrl: string
  let expiresAt: number

  try {
    const link = await createAccountLink({ accountId, returnUrl, refreshUrl })
    linkUrl = link.url
    expiresAt = link.expiresAt
  } catch (err) {
    logger.error({ err, accountId }, 'connect onboard: account link creation failed')
    return NextResponse.json({ error: 'failed to create onboarding link' }, { status: 500 })
  }

  // Step 9: Audit log
  await logAuditAction(
    auth.user.authId,
    'connect_onboarding_started',
    { type: 'stripe_connected_account', id: accountId },
    {
      account_type: type,
      artist_id: artistId ?? null,
      was_existing_account: !!existingAccountId,
    },
    studioId,
  )

  return NextResponse.json({ url: linkUrl, expires_at: expiresAt, account_id: accountId })
}

/**
 * GET /api/billing/connect/status?type=studio|artist&artist_id=optional
 *
 * Returns the current Stripe Connect onboarding status for the studio or an artist.
 * Reads from DB (no live Stripe API call) — webhook keeps DB in sync.
 *
 * Authorization: authenticated session, owner or admin role.
 * Rate limit: apiRatelimit (lighter — read-only).
 *
 * Query params:
 *   type      — 'studio' | 'artist' (default: 'studio')
 *   artist_id — required when type='artist'
 *
 * Response 200:
 *   {
 *     account_id?: string;
 *     type: 'studio' | 'artist';
 *     onboarding_status: 'pending' | 'active' | 'restricted' | 'rejected' | null;
 *     capabilities?: { charges_enabled, payouts_enabled, transfers, tax_reporting_us_1099_nec };
 *     restricted_reason?: string;
 *     requirements_due_by?: string;
 *     enabled: boolean;
 *     enabled_reason?: string;
 *   }
 */
import { type NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { getStudioConnectStatus, getArtistConnectStatus } from '@/lib/stripe/connect-status-query'

export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest): Promise<NextResponse> {
  // Rate limit
  const ip = getClientIp(req)
  const rl = await apiRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }

  // Studio role check — owner or admin only
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json(
      { error: 'owner or admin role required' },
      { status: 403 },
    )
  }

  // Parse query params
  const { searchParams } = new URL(req.url)
  const rawType = searchParams.get('type') ?? 'studio'
  const artistId = searchParams.get('artist_id') ?? undefined

  if (rawType !== 'studio' && rawType !== 'artist') {
    return NextResponse.json(
      { error: 'type must be studio or artist' },
      { status: 400 },
    )
  }

  if (rawType === 'artist' && !artistId) {
    return NextResponse.json(
      { error: 'artist_id is required when type is artist' },
      { status: 400 },
    )
  }

  const supabase = await createClient()
  const studioId = auth.studioId

  try {
    if (rawType === 'studio') {
      const status = await getStudioConnectStatus(supabase, studioId)
      return NextResponse.json({
        account_id: status.account_id ?? undefined,
        type: 'studio',
        onboarding_status: status.onboarding_status,
        capabilities: status.capabilities ?? undefined,
        restricted_reason: status.restricted_reason ?? undefined,
        requirements_due_by: status.requirements_due_by ?? undefined,
        enabled: status.enabled,
        enabled_reason: status.enabled_reason ?? undefined,
      })
    }

    // type === 'artist'
    const status = await getArtistConnectStatus(supabase, studioId, artistId!)
    return NextResponse.json({
      account_id: status.account_id ?? undefined,
      type: 'artist',
      onboarding_status: status.onboarding_status,
      capabilities: status.capabilities ?? undefined,
      restricted_reason: status.restricted_reason ?? undefined,
      requirements_due_by: status.requirements_due_by ?? undefined,
      enabled: status.enabled,
      enabled_reason: status.enabled_reason ?? undefined,
    })
  } catch (err) {
    logger.error({ err, studioId, type: rawType }, 'connect status: query failed')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }
}

/**
 * GET /api/billing/connect/refresh-link?type=studio|artist&artist_id=optional
 *
 * Refreshes an expired Stripe account_link and issues a 302 redirect to the
 * new Stripe-hosted KYC URL.
 *
 * This is the `refresh_url` endpoint passed to Stripe when creating account links.
 * Stripe redirects the user's browser here when the original link has expired.
 * The response MUST be a redirect (302) — Stripe expects to follow it to a new URL.
 *
 * Authorization: authenticated session, owner or admin.
 * Rate limit: authedRatelimit.
 *
 * Query params:
 *   type      — 'studio' | 'artist'
 *   artist_id — required when type='artist'
 */
import { type NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { createAccountLink } from '@/lib/stripe/connect'
import type { ConnectedAccountType } from '@/lib/payments/contracts'

export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest): Promise<NextResponse> {
  // Rate limit
  const ip = getClientIp(req)
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    // Stripe's refresh_url redirect may arrive while the user isn't logged in
    // (e.g. session expired during KYC). Redirect to login with return param.
    const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
    return NextResponse.redirect(
      `${appUrl}/login?return_to=/settings/payments`,
      { status: 302 },
    )
  }

  // Studio role check
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'owner or admin role required' }, { status: 403 })
  }

  // Parse query params
  const { searchParams } = new URL(req.url)
  const rawType = searchParams.get('type') ?? 'studio'
  const artistId = searchParams.get('artist_id') || undefined

  if (rawType !== 'studio' && rawType !== 'artist') {
    return NextResponse.json({ error: 'type must be studio or artist' }, { status: 400 })
  }

  if (rawType === 'artist' && !artistId) {
    return NextResponse.json({ error: 'artist_id required when type is artist' }, { status: 400 })
  }

  const type = rawType as ConnectedAccountType
  const studioId = auth.studioId
  const supabase = await createClient()
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  // Look up the existing account_id for this (studio, type, artist_id)
  const accountQuery = supabase
    .from('stripe_connected_accounts')
    .select('account_id, onboarding_status')
    .eq('studio_id', studioId)
    .eq('type', type)

  if (type === 'artist' && artistId) {
    accountQuery.eq('artist_id', artistId)
  } else {
    accountQuery.is('artist_id', null)
  }

  const { data: existing, error: dbErr } = await accountQuery.maybeSingle()

  if (dbErr) {
    logger.error({ err: dbErr, studioId, type }, 'connect refresh-link: DB lookup failed')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }

  if (!existing) {
    // No account exists — redirect to settings so the user can start onboarding
    return NextResponse.redirect(`${appUrl}/settings/payments`, { status: 302 })
  }

  const accountId = existing.account_id as string

  // If already active, no need to refresh — redirect to settings
  if (existing.onboarding_status === 'active') {
    return NextResponse.redirect(
      `${appUrl}/settings/payments?onboarding=complete&type=${type}`,
      { status: 302 },
    )
  }

  // Generate a fresh account link
  const artistParam = artistId ?? ''
  const returnUrl = `${appUrl}/settings/payments?onboarding=complete&type=${type}`
  const refreshUrl = `${appUrl}/api/billing/connect/refresh-link?type=${type}&artist_id=${artistParam}`

  try {
    const link = await createAccountLink({ accountId, returnUrl, refreshUrl })
    // 302 redirect to Stripe-hosted KYC URL
    return NextResponse.redirect(link.url, { status: 302 })
  } catch (err) {
    logger.error({ err, accountId }, 'connect refresh-link: account link creation failed')
    // Redirect to settings with error flag rather than showing an error page
    return NextResponse.redirect(
      `${appUrl}/settings/payments?onboarding=error`,
      { status: 302 },
    )
  }
}

/**
 * POST /api/billing/connect/onboard
 *
 * Creates a Stripe Connect Express account for the studio or an artist, records it
 * via the stripe_connected_account_create RPC, and returns a Stripe-hosted KYC URL.
 *
 * Authorization: authenticated session, studio owner or admin role.
 * Rate limit: authedRatelimit (60 req/min).
 *
 * Body: { type: 'studio' | 'artist'; artist_id?: string }
 * Response 200: { url: string; expires_at: number; account_id: string }
 * Response 409: { error: 'already_onboarded' } — account already active
 *
 * NOTE: stripe_connected_accounts table is created by Track C migration. Until that
 * migration lands, DB calls against that table will fail at runtime (not compile time)
 * because we use `unknown` casts to work around the absent Supabase-generated types.
 */
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'
import { createConnectAccount, createAccountLink } from '@/lib/stripe/connect'
import type { ConnectedAccountOnboardingStatus, ConnectedAccountType, Currency } from '@/lib/payments/contracts'

export const dynamic = 'force-dynamic'

const BodySchema = z.object({
  type: z.enum(['studio', 'artist']),
  /** Required when type='artist'. UUID of the artist. */
  artist_id: z.string().uuid().optional(),
})

/** Rows returned from stripe_connected_accounts (typed here until Track C migration generates types). */
interface ConnectedAccountLookupRow {
  account_id: string
  onboarding_status: ConnectedAccountOnboardingStatus
}

/** Artist row shape we need for auth check. */
interface ArtistLookupRow {
  id: string
  profile_id: string | null
  studio_id: string
}

/** Profile row. */
interface ProfileLookupRow {
  email: string | null
}

// ---------------------------------------------------------------------------
// POST handler
// ---------------------------------------------------------------------------

export async function POST(req: NextRequest): Promise<NextResponse> {
  // Step 1: Rate limit by IP
  const ip = getClientIp(req)
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Step 2: Auth — require authenticated session
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }

  // Step 3: Studio role check — owner or admin only
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json(
      { error: 'owner or admin role required to manage Connect onboarding' },
      { status: 403 },
    )
  }

  // Step 4: Parse and validate body
  const parsed = BodySchema.safeParse(await req.json().catch(() => ({})))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { type, artist_id: artistId } = parsed.data

  // artist_id is required when type='artist'
  if (type === 'artist' && !artistId) {
    return NextResponse.json(
      { error: 'artist_id is required when type is artist' },
      { status: 400 },
    )
  }

  const supabase = await createClient()
  const studioId = auth.studioId
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  // Step 5: If type='artist', verify artistId belongs to this studio.
  //         Caller must be studio owner/admin OR the artist themselves.
  if (type === 'artist' && artistId) {
    const { data: artistRaw, error: artistErr } = await supabase
      .from('artists')
      .select('id, profile_id, studio_id')
      .eq('id', artistId)
      .eq('studio_id', studioId)
      .maybeSingle()

    if (artistErr) {
      logger.error({ err: artistErr, artistId, studioId }, 'connect onboard: artist lookup failed')
      return NextResponse.json({ error: 'internal error' }, { status: 500 })
    }

    if (!artistRaw) {
      return NextResponse.json(
        { error: 'artist not found in this studio' },
        { status: 404 },
      )
    }

    const artist = artistRaw as unknown as ArtistLookupRow

    // Caller must be studio owner/admin (already checked above) OR the artist themselves.
    // For non-owner callers: their profile_id must match the artist's profile_id.
    const isArtistSelf = artist.profile_id === auth.user.id
    const isOwnerOrAdmin = auth.role === 'owner' || auth.role === 'admin'
    if (!isOwnerOrAdmin && !isArtistSelf) {
      return NextResponse.json(
        { error: 'forbidden: you can only initiate onboarding for yourself or as studio owner/admin' },
        { status: 403 },
      )
    }
  }

  // Step 6: Check if a connected account already exists for this (studio, type, artist_id).
  //
  // stripe_connected_accounts is not yet in the Supabase-generated types (Track C migration pending).
  // We cast through `unknown` to avoid compile errors while keeping runtime correctness.
  let existingAccountId: string | null = null
  let existingOnboardingStatus: ConnectedAccountOnboardingStatus | null = null

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- table absent from types until Track C migration
    const query = (supabase as unknown as { from: (t: string) => any })
      .from('stripe_connected_accounts')
      .select('account_id, onboarding_status')
      .eq('studio_id', studioId)
      .eq('type', type)

    if (type === 'artist' && artistId) {
      query.eq('artist_id', artistId)
    } else {
      query.is('artist_id', null)
    }

    const { data: existing, error: accountErr } = await query.maybeSingle() as {
      data: ConnectedAccountLookupRow | null
      error: { message: string } | null
    }

    if (accountErr) {
      logger.error({ err: accountErr, studioId, type }, 'connect onboard: account lookup failed')
      return NextResponse.json({ error: 'internal error' }, { status: 500 })
    }

    if (existing) {
      existingAccountId = existing.account_id
      existingOnboardingStatus = existing.onboarding_status

      // Already fully onboarded — nothing to do
      if (existingOnboardingStatus === 'active') {
        return NextResponse.json({ error: 'already_onboarded' }, { status: 409 })
      }

      // Has a connected account in non-active state — reuse it, skip creation
      logger.info(
        { accountId: existingAccountId, status: existingOnboardingStatus },
        'connect onboard: reusing existing non-active account',
      )
    }
  } catch (lookupErr) {
    // If the table doesn't exist yet (pre-migration), treat as no account found and proceed
    logger.warn(
      { err: lookupErr, studioId, type },
      'connect onboard: stripe_connected_accounts table not found (migration pending) — creating new account',
    )
  }

  // Step 7: Create a new connected account if none exists
  let accountId: string

  if (!existingAccountId) {
    // Fetch studio currency for defaultCurrency
    const { data: studioRaw, error: studioErr } = await supabase
      .from('studios')
      .select('currency')
      .eq('id', studioId)
      .single()

    if (studioErr || !studioRaw) {
      logger.error({ err: studioErr, studioId }, 'connect onboard: studio lookup failed')
      return NextResponse.json({ error: 'internal error' }, { status: 500 })
    }

    // Use the authenticated user's email from their auth session
    const email = auth.user.email ?? ''
    if (!email) {
      logger.error({ studioId }, 'connect onboard: cannot determine email for Stripe KYC')
      return NextResponse.json({ error: 'user email not available' }, { status: 500 })
    }

    // For artist type, try to get the artist's own profile email
    let resolvedEmail = email
    if (type === 'artist' && artistId) {
      const { data: profileRaw } = await supabase
        .from('profiles')
        .select('email')
        .eq('id', auth.user.id)
        .maybeSingle()
      const profile = profileRaw as unknown as ProfileLookupRow | null
      if (profile?.email) {
        resolvedEmail = profile.email
      }
    }

    // currency: validate against supported Currency union; default to 'usd'
    const rawCurrency = (studioRaw.currency ?? 'usd').toLowerCase()
    const supportedCurrencies: Currency[] = ['usd', 'gbp', 'eur', 'aud', 'cad']
    const defaultCurrency: Currency = supportedCurrencies.includes(rawCurrency as Currency)
      ? (rawCurrency as Currency)
      : 'usd'

    // country: default 'US' (studio country column pending future migration)
    const country = 'US'

    try {
      const result = await createConnectAccount(supabase, {
        studioId,
        type: type as ConnectedAccountType,
        artistId,
        country,
        defaultCurrency,
        email: resolvedEmail,
      })
      accountId = result.accountId
    } catch (err) {
      logger.error({ err, studioId, type }, 'connect onboard: account creation failed')
      return NextResponse.json({ error: 'failed to create connected account' }, { status: 500 })
    }
  } else {
    accountId = existingAccountId
  }

  // Step 8: Generate Stripe-hosted account link for KYC
  const typeParam = type
  const artistParam = artistId ?? ''
  const returnUrl = `${appUrl}/settings/payments?onboarding=complete&type=${typeParam}`
  const refreshUrl = `${appUrl}/api/billing/connect/refresh-link?type=${typeParam}&artist_id=${artistParam}`

  let linkUrl: string
  let expiresAt: number

  try {
    const link = await createAccountLink({ accountId, returnUrl, refreshUrl })
    linkUrl = link.url
    expiresAt = link.expiresAt
  } catch (err) {
    logger.error({ err, accountId }, 'connect onboard: account link creation failed')
    return NextResponse.json({ error: 'failed to create onboarding link' }, { status: 500 })
  }

  // Step 9: Audit log — never throws (failures logged internally)
  await logAuditAction(
    auth.user.authId,
    'connect_onboarding_started',
    { type: 'stripe_connected_account', id: accountId },
    {
      account_type: type,
      artist_id: artistId ?? null,
      was_existing_account: !!existingAccountId,
    },
    studioId,
  )

  return NextResponse.json({ url: linkUrl, expires_at: expiresAt, account_id: accountId })
}

/**
 * GET /api/billing/connect/refresh-link?type=studio|artist&artist_id=optional
 *
 * Refreshes an expired Stripe account_link and issues a 302 redirect to the
 * new Stripe-hosted KYC URL.
 *
 * This is the `refresh_url` endpoint passed to Stripe when creating account links.
 * Stripe redirects the user's browser here when the original link has expired.
 * The response MUST be a redirect (302) — Stripe expects to follow it to a new URL.
 *
 * Authorization: authenticated session, owner or admin.
 * Rate limit: authedRatelimit.
 *
 * Query params:
 *   type      — 'studio' | 'artist'
 *   artist_id — required when type='artist'
 *
 * NOTE: stripe_connected_accounts table is created by Track C migration. Until that
 * migration lands, DB calls against that table will fail at runtime.
 * We use `unknown` casts to avoid compile-time errors from absent generated types.
 */
import { type NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { createAccountLink } from '@/lib/stripe/connect'
import type { ConnectedAccountType, ConnectedAccountOnboardingStatus } from '@/lib/payments/contracts'

export const dynamic = 'force-dynamic'

interface ConnectedAccountLookupRow {
  account_id: string
  onboarding_status: ConnectedAccountOnboardingStatus
}

export async function GET(req: NextRequest): Promise<NextResponse> {
  // Rate limit
  const ip = getClientIp(req)
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    // Stripe's refresh_url redirect may arrive while the user isn't logged in
    // (e.g. session expired during KYC). Redirect to login with return param.
    const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''
    return NextResponse.redirect(
      `${appUrl}/login?return_to=/settings/payments`,
      { status: 302 },
    )
  }

  // Studio role check
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json({ error: 'owner or admin role required' }, { status: 403 })
  }

  // Parse query params
  const { searchParams } = new URL(req.url)
  const rawType = searchParams.get('type') ?? 'studio'
  const artistId = searchParams.get('artist_id') || undefined

  if (rawType !== 'studio' && rawType !== 'artist') {
    return NextResponse.json({ error: 'type must be studio or artist' }, { status: 400 })
  }

  if (rawType === 'artist' && !artistId) {
    return NextResponse.json({ error: 'artist_id required when type is artist' }, { status: 400 })
  }

  const type = rawType as ConnectedAccountType
  const studioId = auth.studioId
  const supabase = await createClient()
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  // Look up the existing account_id for this (studio, type, artist_id)
  let existing: ConnectedAccountLookupRow | null = null

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- table absent from types until Track C migration
    const query = (supabase as unknown as { from: (t: string) => any })
      .from('stripe_connected_accounts')
      .select('account_id, onboarding_status')
      .eq('studio_id', studioId)
      .eq('type', type)

    if (type === 'artist' && artistId) {
      query.eq('artist_id', artistId)
    } else {
      query.is('artist_id', null)
    }

    const { data, error: dbErr } = await query.maybeSingle() as {
      data: ConnectedAccountLookupRow | null
      error: { message: string } | null
    }

    if (dbErr) {
      logger.error({ err: dbErr, studioId, type }, 'connect refresh-link: DB lookup failed')
      return NextResponse.redirect(`${appUrl}/settings/payments?onboarding=error`, { status: 302 })
    }

    existing = data
  } catch (err) {
    logger.error({ err, studioId, type }, 'connect refresh-link: DB query threw (migration pending?)')
    return NextResponse.redirect(`${appUrl}/settings/payments?onboarding=error`, { status: 302 })
  }

  if (!existing) {
    // No account exists — redirect to settings so the user can start onboarding
    return NextResponse.redirect(`${appUrl}/settings/payments`, { status: 302 })
  }

  const accountId = existing.account_id

  // If already active, no need to refresh — redirect to settings
  if (existing.onboarding_status === 'active') {
    return NextResponse.redirect(
      `${appUrl}/settings/payments?onboarding=complete&type=${type}`,
      { status: 302 },
    )
  }

  // Generate a fresh account link
  const artistParam = artistId ?? ''
  const returnUrl = `${appUrl}/settings/payments?onboarding=complete&type=${type}`
  const refreshUrl = `${appUrl}/api/billing/connect/refresh-link?type=${type}&artist_id=${artistParam}`

  try {
    const link = await createAccountLink({ accountId, returnUrl, refreshUrl })
    // 302 redirect to Stripe-hosted KYC URL
    return NextResponse.redirect(link.url, { status: 302 })
  } catch (err) {
    logger.error({ err, accountId }, 'connect refresh-link: account link creation failed')
    return NextResponse.redirect(
      `${appUrl}/settings/payments?onboarding=error`,
      { status: 302 },
    )
  }
}

/**
 * Connect status query helper — Sprint 15.
 *
 * Reads the studio's Stripe Connect state from our DB (no live Stripe API call).
 * The `account.updated` webhook keeps the DB in sync.
 *
 * Consumed by:
 *  - GET /api/billing/connect/status
 *  - Track B: /settings/payments page
 *  - Track B: /dashboard Connect onboarding banner
 *
 * NOTE: stripe_connected_accounts table is created by Track C migration. Until that
 * migration lands, DB calls against that table will fail at runtime. We use `unknown`
 * casts to avoid compile-time errors from absent generated types.
 */
import type { SupabaseClient } from '@supabase/supabase-js'
import type { ConnectedAccountOnboardingStatus } from '@/lib/payments/contracts'
import { RPC } from '@/lib/payments/contracts'
import { logger } from '@/lib/logger'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ConnectStatusResult {
  /** Stripe acct_xxx. Null if no connected account exists yet. */
  account_id: string | null
  onboarding_status: ConnectedAccountOnboardingStatus | null
  capabilities: {
    charges_enabled: boolean
    payouts_enabled: boolean
    transfers: boolean
    tax_reporting_us_1099_nec: boolean
  } | null
  restricted_reason: string | null
  requirements_due_by: string | null
  /**
   * True only when: onboarding_status='active' AND capabilities.charges_enabled=true.
   * Computed in TS as a fallback until Track C's studio_l2_payments_enabled RPC lands.
   */
  enabled: boolean
  /**
   * Human-readable reason when enabled=false. Matches the RPC reason codes defined
   * in StudioL2PaymentsEnabledResult so UI copy can be keyed to these strings.
   */
  enabled_reason: string | null
}

export interface ArtistConnectStatusResult {
  account_id: string | null
  onboarding_status: ConnectedAccountOnboardingStatus | null
  capabilities: {
    charges_enabled: boolean
    payouts_enabled: boolean
    transfers: boolean
    tax_reporting_us_1099_nec: boolean
  } | null
  restricted_reason: string | null
  requirements_due_by: string | null
  enabled: boolean
  enabled_reason: string | null
}

// ---------------------------------------------------------------------------
// Raw DB row shape (mirrors StripeConnectedAccountRow from contracts.ts)
// The actual table is created by Track C migration — we type it here directly.
// ---------------------------------------------------------------------------

interface ConnectedAccountDbRow {
  account_id: string
  onboarding_status: ConnectedAccountOnboardingStatus
  capabilities: {
    charges_enabled: boolean
    payouts_enabled: boolean
    transfers: boolean
    tax_reporting_us_1099_nec: boolean
    [k: string]: boolean | undefined
  } | null
  restricted_reason: string | null
  requirements_due_by: string | null
}

// ---------------------------------------------------------------------------
// computeEnabledFromRow — TS fallback until Track C RPC ships
// ---------------------------------------------------------------------------

function computeEnabledFromRow(
  row: ConnectedAccountDbRow,
): { enabled: boolean; enabled_reason: string | null } {
  if (row.onboarding_status === 'rejected') {
    return { enabled: false, enabled_reason: 'onboarding_rejected' }
  }
  if (row.onboarding_status === 'restricted') {
    return { enabled: false, enabled_reason: 'onboarding_restricted' }
  }
  if (row.onboarding_status === 'pending') {
    return { enabled: false, enabled_reason: 'onboarding_pending' }
  }
  if (row.onboarding_status === 'active') {
    const chargesEnabled = row.capabilities?.charges_enabled === true
    if (!chargesEnabled) {
      return { enabled: false, enabled_reason: 'charges_disabled' }
    }
    return { enabled: true, enabled_reason: null }
  }
  return { enabled: false, enabled_reason: 'onboarding_pending' }
}

// ---------------------------------------------------------------------------
// getStudioConnectStatus
// ---------------------------------------------------------------------------

/**
 * Get the studio's Connect status for UI rendering. Reads from our DB
 * (no Stripe API call) — webhook keeps DB in sync.
 *
 * Tries the studio_l2_payments_enabled RPC first (Track C). Falls back to
 * TS computation if the RPC doesn't exist yet (pre-migration state).
 *
 * Returns a null-safe result: if the studio has no connected account at all,
 * returns { account_id: null, onboarding_status: null, enabled: false, ... }.
 */
export async function getStudioConnectStatus(
  supabase: SupabaseClient,
  studioId: string,
): Promise<ConnectStatusResult> {
  // Read the connected account row for this studio (type='studio').
  // Cast through unknown because stripe_connected_accounts is absent from generated types
  // until Track C migration runs.
  let row: ConnectedAccountDbRow | null = null

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- absent from types until Track C migration
    const { data, error } = await (supabase as unknown as { from: (t: string) => any })
      .from('stripe_connected_accounts')
      .select('account_id, onboarding_status, capabilities, restricted_reason, requirements_due_by')
      .eq('studio_id', studioId)
      .eq('type', 'studio')
      .maybeSingle() as { data: ConnectedAccountDbRow | null; error: { message: string } | null }

    if (error) {
      logger.error({ err: error, studioId }, 'connect-status: failed to read stripe_connected_accounts')
      throw new Error(error.message)
    }

    row = data
  } catch (err) {
    logger.error({ err, studioId }, 'connect-status: stripe_connected_accounts query failed (migration pending?)')
    throw err
  }

  if (!row) {
    return {
      account_id: null,
      onboarding_status: null,
      capabilities: null,
      restricted_reason: null,
      requirements_due_by: null,
      enabled: false,
      enabled_reason: 'no_connected_account',
    }
  }

  // Try the capability RPC (Track C). If not deployed yet, fall back to TS computation.
  try {
    const { data: rpcResult, error: rpcError } = await supabase.rpc(
      RPC.STUDIO_L2_PAYMENTS_ENABLED,
      { p_studio_id: studioId },
    )

    if (!rpcError && rpcResult) {
      const r = rpcResult as { enabled: boolean; reason: string | null }
      return {
        account_id: row.account_id,
        onboarding_status: row.onboarding_status,
        capabilities: row.capabilities ?? null,
        restricted_reason: row.restricted_reason,
        requirements_due_by: row.requirements_due_by,
        enabled: r.enabled,
        enabled_reason: r.reason,
      }
    }

    // RPC returned an error (function not yet deployed) — fall through to TS fallback
    if (rpcError) {
      logger.warn(
        { err: rpcError, studioId },
        'connect-status: studio_l2_payments_enabled RPC not available — using TS fallback',
      )
    }
  } catch (rpcErr) {
    logger.warn(
      { err: rpcErr, studioId },
      'connect-status: studio_l2_payments_enabled RPC threw — using TS fallback',
    )
  }

  const { enabled, enabled_reason } = computeEnabledFromRow(row)

  return {
    account_id: row.account_id,
    onboarding_status: row.onboarding_status,
    capabilities: row.capabilities ?? null,
    restricted_reason: row.restricted_reason,
    requirements_due_by: row.requirements_due_by,
    enabled,
    enabled_reason,
  }
}

// ---------------------------------------------------------------------------
// getArtistConnectStatus
// ---------------------------------------------------------------------------

/**
 * Get an artist's Connect status. Reads from our DB — no Stripe API call.
 *
 * Tries the artist_l2_payouts_enabled RPC first. Falls back to TS computation.
 */
export async function getArtistConnectStatus(
  supabase: SupabaseClient,
  studioId: string,
  artistId: string,
): Promise<ArtistConnectStatusResult> {
  let row: ConnectedAccountDbRow | null = null

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- absent from types until Track C migration
    const { data, error } = await (supabase as unknown as { from: (t: string) => any })
      .from('stripe_connected_accounts')
      .select('account_id, onboarding_status, capabilities, restricted_reason, requirements_due_by')
      .eq('studio_id', studioId)
      .eq('type', 'artist')
      .eq('artist_id', artistId)
      .maybeSingle() as { data: ConnectedAccountDbRow | null; error: { message: string } | null }

    if (error) {
      logger.error(
        { err: error, studioId, artistId },
        'connect-status: failed to read stripe_connected_accounts for artist',
      )
      throw new Error(error.message)
    }

    row = data
  } catch (err) {
    logger.error({ err, studioId, artistId }, 'connect-status: artist query failed (migration pending?)')
    throw err
  }

  if (!row) {
    return {
      account_id: null,
      onboarding_status: null,
      capabilities: null,
      restricted_reason: null,
      requirements_due_by: null,
      enabled: false,
      enabled_reason: 'no_connected_account',
    }
  }

  // Try the capability RPC (Track C)
  try {
    const { data: rpcResult, error: rpcError } = await supabase.rpc(
      RPC.ARTIST_L2_PAYOUTS_ENABLED,
      { p_artist_id: artistId },
    )

    if (!rpcError && rpcResult) {
      const r = rpcResult as { enabled: boolean; reason: string | null }
      return {
        account_id: row.account_id,
        onboarding_status: row.onboarding_status,
        capabilities: row.capabilities ?? null,
        restricted_reason: row.restricted_reason,
        requirements_due_by: row.requirements_due_by,
        enabled: r.enabled,
        enabled_reason: r.reason,
      }
    }

    if (rpcError) {
      logger.warn(
        { err: rpcError, artistId },
        'connect-status: artist_l2_payouts_enabled RPC not available — using TS fallback',
      )
    }
  } catch (rpcErr) {
    logger.warn(
      { err: rpcErr, artistId },
      'connect-status: artist_l2_payouts_enabled RPC threw — using TS fallback',
    )
  }

  // TS fallback for artist: active + payouts_enabled + transfers
  let enabled = false
  let enabled_reason: string | null = null

  if (row.onboarding_status === 'rejected') {
    enabled_reason = 'onboarding_rejected'
  } else if (row.onboarding_status === 'restricted') {
    enabled_reason = 'onboarding_restricted'
  } else if (row.onboarding_status === 'pending') {
    enabled_reason = 'onboarding_pending'
  } else if (row.onboarding_status === 'active') {
    const payoutsEnabled = row.capabilities?.payouts_enabled === true
    const transfersEnabled = row.capabilities?.transfers === true
    if (!payoutsEnabled) {
      enabled_reason = 'payouts_disabled'
    } else if (!transfersEnabled) {
      enabled_reason = 'transfers_disabled'
    } else {
      enabled = true
    }
  } else {
    enabled_reason = 'onboarding_pending'
  }

  return {
    account_id: row.account_id,
    onboarding_status: row.onboarding_status,
    capabilities: row.capabilities ?? null,
    restricted_reason: row.restricted_reason,
    requirements_due_by: row.requirements_due_by,
    enabled,
    enabled_reason,
  }
}

/**
 * GET /api/billing/connect/status?type=studio|artist&artist_id=optional
 *
 * Returns the current Stripe Connect onboarding status for the studio or an artist.
 * Reads from DB (no live Stripe API call) — webhook keeps DB in sync.
 *
 * Authorization: authenticated session, owner or admin role.
 * Rate limit: apiRatelimit (lighter — read-only).
 *
 * Query params:
 *   type      — 'studio' | 'artist' (default: 'studio')
 *   artist_id — required when type='artist'
 *
 * Response 200:
 *   {
 *     account_id?: string;
 *     type: 'studio' | 'artist';
 *     onboarding_status: 'pending' | 'active' | 'restricted' | 'rejected' | null;
 *     capabilities?: { charges_enabled, payouts_enabled, transfers, tax_reporting_us_1099_nec };
 *     restricted_reason?: string;
 *     requirements_due_by?: string;
 *     enabled: boolean;
 *     enabled_reason?: string;
 *   }
 */
import { type NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { getStudioConnectStatus, getArtistConnectStatus } from '@/lib/stripe/connect-status-query'

export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest): Promise<NextResponse> {
  // Rate limit
  const ip = getClientIp(req)
  const rl = await apiRatelimit.limit(ip)
  if (!rl.success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }

  // Studio role check — owner or admin only
  if (auth.role !== 'owner' && auth.role !== 'admin') {
    return NextResponse.json(
      { error: 'owner or admin role required' },
      { status: 403 },
    )
  }

  // Parse query params
  const { searchParams } = new URL(req.url)
  const rawType = searchParams.get('type') ?? 'studio'
  const artistId = searchParams.get('artist_id') ?? undefined

  if (rawType !== 'studio' && rawType !== 'artist') {
    return NextResponse.json(
      { error: 'type must be studio or artist' },
      { status: 400 },
    )
  }

  if (rawType === 'artist' && !artistId) {
    return NextResponse.json(
      { error: 'artist_id is required when type is artist' },
      { status: 400 },
    )
  }

  const supabase = await createClient()
  const studioId = auth.studioId

  try {
    if (rawType === 'studio') {
      const status = await getStudioConnectStatus(supabase, studioId)
      return NextResponse.json({
        ...(status.account_id !== null ? { account_id: status.account_id } : {}),
        type: 'studio',
        onboarding_status: status.onboarding_status,
        ...(status.capabilities !== null ? { capabilities: status.capabilities } : {}),
        ...(status.restricted_reason !== null ? { restricted_reason: status.restricted_reason } : {}),
        ...(status.requirements_due_by !== null ? { requirements_due_by: status.requirements_due_by } : {}),
        enabled: status.enabled,
        ...(status.enabled_reason !== null ? { enabled_reason: status.enabled_reason } : {}),
      })
    }

    // type === 'artist'
    const status = await getArtistConnectStatus(supabase, studioId, artistId!)
    return NextResponse.json({
      ...(status.account_id !== null ? { account_id: status.account_id } : {}),
      type: 'artist',
      onboarding_status: status.onboarding_status,
      ...(status.capabilities !== null ? { capabilities: status.capabilities } : {}),
      ...(status.restricted_reason !== null ? { restricted_reason: status.restricted_reason } : {}),
      ...(status.requirements_due_by !== null ? { requirements_due_by: status.requirements_due_by } : {}),
      enabled: status.enabled,
      ...(status.enabled_reason !== null ? { enabled_reason: status.enabled_reason } : {}),
    })
  } catch (err) {
    logger.error({ err, studioId, type: rawType }, 'connect status: query failed')
    return NextResponse.json({ error: 'internal error' }, { status: 500 })
  }
}

